const port = (id, label, position, tone = 'signal') => ({ id, label, className: `lab-port--${tone} ${position}` });

const box = (id, label, badge, x, y, ports, tone = 'purple') => ({
  id, type: 'systembox', label, badge, x, y, ports, tone,
});

const base = (ports, x = 25, y = 50, label = 'Arduino base controller') => box('base', label, 'ARDUINO BASE', x, y, ports, 'cyan');
const driver = (ports, x = 58, y = 50, label = 'Dual H-bridge motor driver') => box('driver', label, 'H-BRIDGE', x, y, ports, 'orange');
const computer = (ports, x = 74, y = 50, label = 'Cerebro computer') => ({ id: 'computer', type: 'computer', label, x, y, ports });
const tread = (id, side, x, y) => ({
  id, type: 'tread', label: `${side} ROB tread`, side, x, y,
  ports: [port('a', 'A', 'port-left-top'), port('b', 'B', 'port-left-bottom'), port('enc', 'ENC', 'port-right-middle')],
});
const control = (id, label, set, readout) => ({ id, label, set, readout });
const objective = (text, key) => [text, (state) => Boolean(state[key])];
const mission = (config) => ({ ...config, objectives: config.objectiveSpecs.map(([text, key]) => objective(text, key)) });

const motorLogicPorts = [
  port('v5', '5V', 'port-left-top', 'positive'), port('gnd', 'GND', 'port-left-bottom', 'ground'),
  port('d5', '~5', 'port-right-top'), port('d7', 'D7', 'port-right-middle'), port('d8', 'D8', 'port-right-bottom'),
];
const motorDriverPorts = [
  port('vcc', 'VCC', 'port-left-top', 'positive'), port('gnd', 'GND', 'port-left-bottom', 'ground'),
  port('ena', 'ENA', 'port-top-left'), port('in1', 'IN1', 'port-top-right'), port('in2', 'IN2', 'port-bottom-left'),
  port('vm', 'VM', 'port-bottom-right', 'positive'), port('m1a', 'A', 'port-right-top'), port('m1b', 'B', 'port-right-bottom'),
  port('pwrGnd', 'P−', 'port-bottom-middle', 'ground'),
];
const dualBasePorts = [
  port('driveL', 'L CMD', 'port-right-top'), port('driveR', 'R CMD', 'port-right-bottom'),
  port('gnd', 'GND', 'port-left-bottom', 'ground'), port('v5', '5V', 'port-left-top', 'positive'),
];
const dualDriverPorts = [
  port('logicL', 'L IN', 'port-left-top'), port('logicR', 'R IN', 'port-left-bottom'),
  port('vm', 'VM', 'port-top-middle', 'positive'), port('pwrGnd', 'P−', 'port-bottom-middle', 'ground'),
  port('m1a', 'L A', 'port-right-top'), port('m1b', 'L B', 'port-right-middle'),
  port('m2a', 'R A', 'port-right-bottom'), port('m2b', 'R B', 'port-bottom-right'),
];

